    include_str!("../../ackplane-server/src/supervisor_store/mod.rs");
const SUPERVISOR_STORE_READS_RS: &str =
    include_str!("../../ackplane-server/src/supervisor_store/reads.rs");
const SUPERVISOR_STORE_SOURCES: &[&str] = &[SUPERVISOR_STORE_MOD_RS, SUPERVISOR_STORE_READS_RS];

#[test]
fn supervisor_routes_are_read_only_and_check_containment_before_queries() {
    for route in [
        "/api/v1/repositories/:repository_id/supervisors",
        "/api/v1/repositories/:repository_id/supervisors/:supervisor_id/sessions",
        "/api/v1/repositories/:repository_id/supervisors/:supervisor_id/sessions/:session_id/lifecycle",
    ] {
        assert!(
            SUPERVISOR_API_RS.contains(route),
            "supervisor router must register {route}"
        );
    }
    assert_eq!(SUPERVISOR_API_RS.matches("get(").count(), 3);
    for mutation in ["post(", "put(", "patch(", "delete("] {
        assert!(
            !SUPERVISOR_API_RS.contains(mutation),
            "supervisor router must not register mutation verb {mutation}"
        );
    }
    assert!(
        function_body(SUPERVISOR_API_RS, "supervisor_inventory")
            .contains("ensure_repository_visible(&state, &repository_id).await?"),
        "inventory must establish tenant-scoped repository visibility before reading supervisors"
    );
    for handler in ["supervisor_sessions", "session_lifecycle"] {
        assert!(
            function_body(SUPERVISOR_API_RS, handler).contains(
                "ensure_supervisor_visible(&state, &repository_id, &supervisor_id).await?"
            ),
            "{handler} must verify the supervisor belongs to the selected tenant and repository"
        );
    }
    assert!(
        function_body(SUPERVISOR_API_RS, "ensure_supervisor_visible")
            .contains("ensure_repository_visible(state, repository_id).await?"),
        "supervisor containment must begin with tenant-scoped repository visibility"
    );
}

#[test]
fn supervisor_store_direct_queries_carry_the_tenant_scope() {
    for method in [
        "record_heartbeat",
        "record_heartbeat_at",
        "record_session",
        "list_supervisors",
        "list_supervisors_at",
        "list_sessions",
        "session",
        "lifecycle_history",
    ] {
        assert!(
            method_signature(SUPERVISOR_STORE_SOURCES, method)
                .is_some_and(|signature| signature.contains("tenant_id: &str")),
            "SupervisorStore::{method} must carry the tenant scope explicitly"
        );
    }
    for scoped_request in [
        "registration: &SupervisorRegistration",
        "request: &SupervisorLifecycleReceiptRequest",
    ] {
        assert!(
            SUPERVISOR_STORE_MOD_RS.contains(scoped_request),
            "typed write requests must retain their tenant and repository identity"
        );
    }
}

fn function_body<'a>(source: &'a str, name: &str) -> &'a str {
    let marker = format!("async fn {name}(");
    let function_start = source
        .find(&marker)
        .unwrap_or_else(|| panic!("expected supervisor handler {name}"));
    let body_start = source[function_start..]
        .find('{')
        .map(|offset| function_start + offset)
        .unwrap_or_else(|| panic!("expected opening brace for supervisor handler {name}"));
    let body_end = balanced_braces(source, body_start)
        .unwrap_or_else(|| panic!("expected closing brace for supervisor handler {name}"));
    &source[body_start..body_end]
}

fn method_signature<'a>(sources: &[&'a str], name: &str) -> Option<&'a str> {
    sources
        .iter()
        .find_map(|source| method_signature_in(source, name))
}

fn method_signature_in<'a>(source: &'a str, name: &str) -> Option<&'a str> {
    let marker = format!("pub async fn {name}(");
    let method_start = source.find(&marker)?;
    let params_start = method_start + marker.len() - 1;
    let params_end = balanced_parens(source, params_start)?;
    Some(&source[params_start..params_end])
}

fn balanced_braces(source: &str, open: usize) -> Option<usize> {
    let mut depth = 0_i32;
    for (offset, character) in source[open..].char_indices() {
        match character {
            '{' => depth += 1,
            '}' => {
                depth -= 1;
                if depth == 0 {
                    return Some(open + offset + 1);
                }
            }
            _ => {}
        }
    }
    None
}

fn balanced_parens(source: &str, open: usize) -> Option<usize> {
    let mut depth = 0_i32;
    for (offset, character) in source[open..].char_indices() {
        match character {
            '(' => depth += 1,
            ')' => {
                depth -= 1;
                if depth == 0 {
                    return Some(open + offset + 1);
                }
            }
            _ => {}
        }
    }
    None
}
